/*
 * HUD library (sdk/lib/hud.c) in the GDB simulator against the mocks in fw.S: gpi_get_glyph serves
 * the English font from glyphs.c, the image table holds the stock live-view images of images.c (both
 * generated by test_hud_sim.py from the stock firmware), the rest is sim_hud.h; the font resource is
 * plain memory.
 * Each element of `cases` is rendered and its rectangle in buffer 0 dumped to stdout for
 * test_hud_sim.py, which compares it with the Python font decoder. plugin_main sets sim_exit_code to
 * the mask of failed checks below (0 = pass; the exit status has 8 bits).
 */
#include "sim_hud.h"

#define SIM_FONT_ID 15u

enum {
	SIM_FAIL_SETUP = 1,	/* init, add or a text did not return 0 */
	SIM_FAIL_REFUSE = 2,	/* bad rectangle, missing glyph or image, no font: refused, element
				   unchanged; LV digits need no font */
	SIM_FAIL_BOTH = 4,	/* text paints both buffers */
	SIM_FAIL_FRAME = 8,	/* the hook restores the shown buffer and counts the erase; not for
				   show_front != 0 */
	SIM_FAIL_HIDDEN = 16,	/* hidden state: no copy, and no erase counted afterwards */
	SIM_FAIL_OVERRIDE = 32,	/* one-layer override selects the other buffer */
	SIM_FAIL_HIDE = 64,	/* hide clears now and at the next two ticks only */
	SIM_FAIL_MASK = 128,	/* masked layer: text publishes without painting, the hook draws later */
};

struct sim_glyph {
	uint16_t w, h;
	const uint8_t *bmp;
};

extern const struct sim_glyph sim_font[128];	/* glyphs.c */
static uint32_t sim_font_list[1] = { SIM_FONT_ID };
static uint32_t sim_font_res[2];

uint32_t c_gpi_get_glyph(void)
{
	const uint16_t *key = (const uint16_t *)mreg[0];
	struct sim_glyph *out = (struct sim_glyph *)mreg[1];

	if (key[0] == SIM_FONT_ID && key[2] < 128)
		*out = sim_font[key[2]];
	else
		*out = (struct sim_glyph){ 0 };
	return 0;
}

struct sim_case {
	struct fenykl_hud_elem e;
	const char *text;
};

static struct sim_case cases[] = {
	/* focus distance box: black, centred */
	{ { .x = 304, .y = 52, .w = 112, .h = 36, .bg = FENYKL_HUD_BLACK, .align = FENYKL_HUD_CENTER,
	    .ink = FENYKL_HUD_WHITE }, "0.25 m" },
	/* every spacing rule, transparent */
	{ { .x = 16, .y = 120, .w = 160, .h = 36, .bg = FENYKL_HUD_CLEAR, .align = FENYKL_HUD_LEFT,
	    .ink = FENYKL_HUD_WHITE }, "+12.3:4/5-6\"" },
	/* several lines, each aligned by its own width; no spacing adjustment at a line end */
	{ { .x = 400, .y = 200, .w = 64, .h = 100, .bg = FENYKL_HUD_TRANSLUCENT,
	    .align = FENYKL_HUD_RIGHT, .ink = { 0x0D, 0x0E, 0x0F } }, "inf\n12:\n.5" },
	/* clipped right and bottom */
	{ { .x = 600, .y = 400, .w = 40, .h = 30, .bg = FENYKL_HUD_BLACK, .align = FENYKL_HUD_LEFT,
	    .ink = FENYKL_HUD_WHITE }, "12345" },
	/* LV style: main's focus and DoF blocks (main.h), every image and a letter in other ink (the
	   images' white takes it), centred and clipped */
	{ { .x = 20, .y = 253, .w = 56, .h = 65, .bg = FENYKL_HUD_CLEAR, .align = FENYKL_HUD_LEFT,
	    .style = FENYKL_HUD_LV, .ink = FENYKL_HUD_WHITE }, "FD\n4290\nkm" },
	{ { .x = 20, .y = 327, .w = 56, .h = 65, .bg = FENYKL_HUD_CLEAR, .align = FENYKL_HUD_LEFT,
	    .style = FENYKL_HUD_LV, .ink = FENYKL_HUD_WHITE }, "DoF\n2.10\nm" },
	{ { .x = 200, .y = 330, .w = 204, .h = 23, .bg = FENYKL_HUD_BLACK, .align = FENYKL_HUD_RIGHT,
	    .style = FENYKL_HUD_LV, .ink = { 0x0D, 0x0E, 0x0F } }, "+67:89-0% cm" },
	{ { .x = 664, .y = 460, .w = 40, .h = 20, .bg = FENYKL_HUD_TRANSLUCENT,
	    .align = FENYKL_HUD_CENTER, .style = FENYKL_HUD_LV, .ink = FENYKL_HUD_WHITE }, "inf3W" },
};

#define SIM_CASES (sizeof(cases) / sizeof(cases[0]))

/* "#### x y w h bg align style ink0 ink1 ink2 text\n" ('\n' in the text as '|'), then the rectangle
   of buffer 0, row by row */
static void sim_dump(const struct sim_case *k)
{
	const struct fenykl_hud_elem *e = &k->e;
	const int v[] = { e->x, e->y, e->w, e->h, e->bg, e->align, e->style, e->ink[0], e->ink[1],
			  e->ink[2] };
	char line[96] = "#### ", *o = line + 5;

	for (unsigned int i = 0; i < sizeof(v) / sizeof(v[0]); i++)
		o = sim_dec(o, v[i]);
	for (const char *s = k->text; *s; s++)
		*o++ = *s == '\n' ? '|' : *s;
	*o++ = '\n';
	sim_write(line, (unsigned int)(o - line));
	for (int r = 0; r < e->h; r++)
		sim_write((const void *)sim_px(SIM_BUF0, e, r, 0), (unsigned int)e->w);
}

static int sim_refusals(void)
{
	struct fenykl_hud_elem bad = { .x = 2, .y = 0, .w = 40, .h = 36 };
	struct fenykl_hud_elem *e = &cases[0].e;
	uint32_t pub = e->pub;

	if (fenykl_hud_add(&bad) != FENYKL_HUD_ERECT)
		return 0;
	bad = (struct fenykl_hud_elem){ .x = 700, .y = 0, .w = 40, .h = 36 };
	if (fenykl_hud_add(&bad) != FENYKL_HUD_ERECT)
		return 0;
	if (fenykl_hud_text(e, "1\x7f") != FENYKL_HUD_EGLYPH ||
	    fenykl_hud_text(e, "1234567890123") != FENYKL_HUD_EGLYPH)
		return 0;
	sim_font_list[0] = 0;
	int r = fenykl_hud_text(e, "1");
	int lv_digits = fenykl_hud_text_width(FENYKL_HUD_LV, "-1.0:");
	int lv_letter = fenykl_hud_text_width(FENYKL_HUD_LV, "1 m");

	sim_font_list[0] = SIM_FONT_ID;
	if (r != FENYKL_HUD_ENOFONT || e->pub != pub || lv_digits != 3 * 13 + 2 * 6 ||
	    lv_letter != FENYKL_HUD_ENOFONT)
		return 0;
	if (fenykl_hud_text_width(FENYKL_HUD_LV, "1\x7f") != FENYKL_HUD_EGLYPH ||
	    fenykl_hud_text_width(FENYKL_HUD_LV, "1\n.0-\n2") != 2 * 13 + 6)
		return 0;
	SIM_U32(SIM_IMAGE_TABLE) = 0;
	r = fenykl_hud_text_width(FENYKL_HUD_LV, "1");
	SIM_U32(SIM_IMAGE_TABLE) = (uint32_t)sim_images;
	return r == FENYKL_HUD_EGLYPH;
}

void plugin_main(uint32_t load_base, uint32_t image_size)
{
	(void)load_base;
	(void)image_size;
	struct fenykl_hud_buf buf[2];
	struct fenykl_hud_stats st;
	int fail = 0;

	sim_setup_memory();
	sim_font_res[1] = (uint32_t)sim_font_list;
	SIM_U32(SIM_FONT_RES) = (uint32_t)sim_font_res;
	if (fenykl_hud_init(FENYKL_HUD_INFO_SCREENS, buf) != 0) {
		sim_exit_code = SIM_FAIL_SETUP;
		return;
	}
	for (unsigned int i = 0; i < SIM_CASES; i++) {
		struct fenykl_hud_elem *e = &cases[i].e;

		sim_fill(SIM_BUF0, e, SIM_GUI);
		sim_fill(SIM_BUF1, e, SIM_GUI);
		if (fenykl_hud_add(e) != 0 || fenykl_hud_text(e, cases[i].text) != 0)
			fail |= SIM_FAIL_SETUP;
		if (!sim_same(e))
			fail |= SIM_FAIL_BOTH;
		sim_dump(&cases[i]);
	}
	if (!sim_refusals())
		fail |= SIM_FAIL_REFUSE;

	struct fenykl_hud_elem *e = &cases[0].e;

	/* The GUI's batch painted over the box in buffer 1, which is about to be shown. */
	sim_fill(SIM_BUF1, e, SIM_GUI);
	SIM_U8(SIM_DRAW_BUF) = 1;
	fenykl_hud_frame(0);
	fenykl_hud_get_stats(&st);
	if (!sim_same(e) || st.erased != 1 || st.drawn != SIM_CASES || st.shows != 1)
		fail |= SIM_FAIL_FRAME;

	/* Multi View (0x06): nothing copied; the first copy afterwards is no erase. */
	SIM_U8(SIM_STATE) = 0x06;
	sim_fill(SIM_BUF1, e, SIM_GUI);
	fenykl_hud_frame(0);
	fenykl_hud_get_stats(&st);
	if (!sim_all(SIM_BUF1, e, SIM_GUI) || st.hidden != SIM_CASES)
		fail |= SIM_FAIL_HIDDEN;
	SIM_U8(SIM_STATE) = 0x04;
	fenykl_hud_frame(0);
	fenykl_hud_get_stats(&st);
	if (!sim_same(e) || st.erased != 1)
		fail |= SIM_FAIL_HIDDEN;

	/* One-layer override for layer 1: buffer 1 ^ 1 is shown. */
	SIM_U8(SIM_ONE_MODE) = 2;
	SIM_U16(SIM_ONE_LAYER) = 1;
	SIM_U8(SIM_ONE_BUF) = 1;
	sim_fill(SIM_BUF0, e, SIM_GUI);
	fenykl_hud_frame(0);
	fenykl_hud_get_stats(&st);
	if (!sim_same(e) || st.overrides != SIM_CASES)
		fail |= SIM_FAIL_OVERRIDE;
	SIM_U8(SIM_ONE_MODE) = 0;

	sim_fill(SIM_BUF1, e, SIM_GUI);
	fenykl_hud_frame(1);
	fenykl_hud_get_stats(&st);
	if (!sim_all(SIM_BUF1, e, SIM_GUI) || st.shows != 4 || st.updates != 5)
		fail |= SIM_FAIL_FRAME;

	fenykl_hud_hide(e);
	if (!sim_all(SIM_BUF0, e, FENYKL_HUD_CLEAR) || !sim_all(SIM_BUF1, e, FENYKL_HUD_CLEAR))
		fail |= SIM_FAIL_HIDE;
	for (int t = 0; t < 3; t++) {
		sim_fill(SIM_BUF0, e, SIM_GUI);
		fenykl_hud_frame(0);
		fenykl_hud_tick();
		if (sim_all(SIM_BUF0, e, FENYKL_HUD_CLEAR) != (t < 2))
			fail |= SIM_FAIL_HIDE;
	}

	/* Layer 1 masked: published, not painted; the first unmasked frame draws it. A buffer that
	   still holds an older value of an element is no erase. */
	fenykl_hud_get_stats(&st);
	uint32_t erased = st.erased;

	SIM_U16(SIM_HIDE_MASK) = 0x10;
	sim_fill(SIM_BUF0, e, SIM_GUI);
	if (fenykl_hud_text(e, "inf") != 0 || !sim_all(SIM_BUF0, e, SIM_GUI) ||
	    fenykl_hud_text(&cases[1].e, "9") != 0)
		fail |= SIM_FAIL_MASK;
	SIM_U16(SIM_HIDE_MASK) = 0;
	SIM_U8(SIM_DRAW_BUF) = 0;
	fenykl_hud_frame(0);
	fenykl_hud_get_stats(&st);
	if (sim_all(SIM_BUF0, e, SIM_GUI) || sim_all(SIM_BUF0, e, FENYKL_HUD_BLACK) ||
	    st.erased != erased)
		fail |= SIM_FAIL_MASK;
	sim_exit_code = (uint32_t)fail;
}
